package co.edu.uts.web;import co.edu.uts.data.Database;import jakarta.servlet.http.*;import java.util.*;import org.mindrot.jbcrypt.BCrypt;public class ActionBean{private HttpServletRequest r;private Map<String,Object>u;private String redirect;public void setRequest(HttpServletRequest x){r=x;u=(Map<String,Object>)x.getSession().getAttribute("user");Database.init();}public String getRedirect(){return redirect;}private String p(String n){return r.getParameter(n);}private void need(String...a){if(u==null||Arrays.stream(a).noneMatch(x->x.equals(u.get("rol"))))throw new SecurityException("Sin permisos.");}public String process(){if(!"POST".equals(r.getMethod())||!Objects.equals(r.getSession().getAttribute("csrf"),p("csrf")))return "";try{String a=p("action");if("createIdea".equals(a)){need("ESTUDIANTE","ADMIN","COMITE");Database.update("INSERT INTO idea(titulo,descripcion,nivel,estado,creador_id)VALUES(?,?,?,'PENDIENTE',?)",p("titulo"),p("descripcion"),p("nivel"),u.get("id"));}else if("selectIdea".equals(a)){need("ESTUDIANTE");Database.update("INSERT IGNORE INTO idea_estudiante(idea_id,estudiante_id)VALUES(?,?)",p("ideaId"),u.get("id"));}else if("createProject".equals(a)){need("ADMIN","COMITE");Database.update("INSERT INTO proyecto(codigo,idea_id,modalidad,estado)VALUES(?,?,?,'ACTIVO')",p("codigo"),p("ideaId"),p("modalidad"));}else if("document".equals(a)){need("ESTUDIANTE","ADMIN","COMITE","DIRECTOR");Database.update("INSERT INTO documento(proyecto_id,tipo,url)VALUES(?,?,?)",p("proyectoId"),p("tipo"),p("url"));}else if("pqrs".equals(a)){Database.update("INSERT INTO pqrs(usuario_id,asunto,descripcion)VALUES(?,?,?)",u.get("id"),p("asunto"),p("descripcion"));}else if("createUser".equals(a)){need("ADMIN");Database.update("INSERT INTO usuario(documento,nombre,correo,contrasena,rol)VALUES(?,?,?,?,?)",p("documento"),p("nombre"),p("correo"),BCrypt.hashpw(p("contrasena"),BCrypt.gensalt(10)),p("rol"));}else if("readNotifications".equals(a))Database.update("UPDATE notificacion SET leida=TRUE");String x=p("returnPage");redirect=r.getContextPath()+"/"+(x!=null&&x.matches("[a-z-]+\\.jsp")?x:"inicio.jsp");}catch(Exception e){}return "";} }